    ("terraform-provider-cache", "Provider Plugin Cache & Init Performance", "operations", "intermediate", "A plugin cache avoids repeated downloads in developer and CI environments. Keep checksum verification and platform compatibility; do not share a mutable cache across untrusted jobs.", "TF_PLUGIN_CACHE_DIR=.terraform.d/plugin-cache terraform init"),
    ("terraform-workspace-isolation", "Separate State per Account & Team", "state", "advanced", "Separate backends, identities and roots where teams need independent blast radius or access control. Workspace naming alone is not a security boundary.", "Account-specific backend key and deploy role for each environment"),
    ("terraform-drift-alert", "Scheduled Plan & Drift Reporting", "operations", "intermediate", "Scheduled refresh plans detect unmanaged changes and can publish a report without applying. Route drift by resource owner and distinguish approved emergency changes from accidental configuration gaps.", "Nightly plan -detailed-exitcode; report drift without auto-apply"),
